/**
 * Security Layer Tests
 */

import { describe, it, expect } from 'vitest';
import {
  stripHtml,
  escapeHtml,
  sanitizeSql,
  sanitizeUrl,
  isValidEmail,
  isValidUuid,
  validatePassword,
  sanitizeObject,
  isValidProjectName,
  isValidIdentifier,
  safeJsonParse,
} from '../src/security/validation';
import {
  generateCsrfToken,
  validateCsrfToken,
} from '../src/security/csrf';
import {
  buildCspString,
} from '../src/security/csp';
import {
  hashPassword,
  verifyPassword,
  generateSecureToken,
  sha256,
  hmacSha256,
  safeCompare,
  maskSensitiveData,
  sanitizeHeaders,
  encrypt,
  decrypt,
} from '../src/security/secure-storage';
import {
  verifyToken,
  createToken,
  decodeToken,
} from '../src/security/auth.middleware';
import {
  createRateLimiter,
  authRateLimiter,
  apiRateLimiter,
  buildRateLimiter,
} from '../src/security/rate-limit';
import { DEFAULT_CSP_DIRECTIVES } from '../src/security/types';

describe('Security Layer — Validation & Sanitization', () => {
  describe('stripHtml', () => {
    it('should strip HTML tags', () => {
      expect(stripHtml('<script>alert(1)</script>')).toBe('alert(1)');
      expect(stripHtml('<p>Hello</p>')).toBe('Hello');
      expect(stripHtml('No tags')).toBe('No tags');
    });
  });

  describe('escapeHtml', () => {
    it('should escape HTML special characters', () => {
      expect(escapeHtml('<script>')).toBe('&lt;script&gt;');
      expect(escapeHtml('"test"')).toBe('&quot;test&quot;');
      expect(escapeHtml("'test'")).toBe('&#x27;test&#x27;');
    });
  });

  describe('sanitizeSql', () => {
    it('should escape single quotes', () => {
      expect(sanitizeSql("O'Brien")).toBe("O''Brien");
    });
  });

  describe('sanitizeUrl', () => {
    it('should strip javascript: protocol', () => {
      expect(sanitizeUrl('javascript:alert(1)')).toBe('');
      expect(sanitizeUrl('https://example.com')).toBe('https://example.com');
    });
  });

