  type: 'AdvancedMath';
  properties: {
    operation: 'Sin' | 'Cos' | 'Tan' | 'ASin' | 'ACos' | 'ATan' | 'Log' | 'Exp' | 'Sqrt' | 'Abs' | 'Floor' | 'Ceil' | 'Round';
  };
