import { BaseComponent } from "../ecs/index.js";
import { Mat3, Mat4, Quat, Vec3, composeMat4, createMat4, createQuat, createVec3, decomposeMat4 } from "../math/math.js";
import type { Entity } from "../ecs/types.js";
