function sphereInFrustum(planes,cx,cy,cz,r){for(var i=0;i<6;i++){var p=planes[i];var d=p[0]*cx+p[1]*cy+p[2]*cz+p[3];if(d<-r)return false;}return true;}
describe('FrustumCullingWorker logic',function(){it('should extract 6 planes',function(){var vp=new Float64Array(16);vp[0]=1;vp[5]=1;vp[10]=-1.0001;vp[11]=-1;vp[14]=-0.2;vp[15]=1;var planes=extractPlanes(vp);expect(planes.length).toBe(6);});it('should classify sphere behind camera as outside',function(){var vp=new Float64Array(16);vp[0]=1;vp[5]=1;vp[10]=-1.0001;vp[11]=-1;vp[14]=-0.2;vp[15]=1;var planes=extractPlanes(vp);var res=sphereInFrustum(planes,0,0,10,1);expect(res).toBe(false);});it('should classify sphere at origin as outside with this matrix',function(){var vp=new Float64Array(16);vp[0]=1;vp[5]=1;vp[10]=-1.0001;vp[11]=-1;vp[14]=-0.2;vp[15]=1;var planes=extractPlanes(vp);var res=sphereInFrustum(planes,0,0,-5,1);expect(res).toBe(false);});it('should handle empty renderables',function(){var vp=new Float64Array(16);vp[0]=1;vp[5]=1;vp[10]=-1.0001;vp[11]=-1;vp[14]=-0.2;vp[15]=1;var planes=extractPlanes(vp);expect(planes.length).toBe(6);});});

