function computeLOD(renderables,lodLevels){var result=[];for(var i=0;i<renderables.length;i++){var r=renderables[i];var dist=r.distance||0;var sel=0;for(var j=0;j<lodLevels.length;j++){if(dist<=lodLevels[j].maxDistance){sel=lodLevels[j].level;break;}}result.push({id:r.id,lodLevel:sel});}return result;}
