    { id: `${id}-in-b`, name: 'b', type: 'bool', direction: 'input' }
  ];

  return {
    id,
    type: 'LogicOperation',
    position: { x: 0, y: 0 },
    inputs,
    outputs: [
      { id: `${id}-out-result`, name: 'result', type: 'bool', direction: 'output' }
    ],
    properties: {
      operation
    }
  };
}

