  private allocateHandle(body: RAPIER.RigidBody): number {
    if (this.freeIndices.length > 0) {
      const index = this.freeIndices.pop()!;
      this.bodies[index] = undefined;
      this.bodyToIndex.set(body, index);
      return index;
