function getPermissionsForRoles(roles: Role[]): string[] {
  const permissions = new Set<string>();
  for (const role of roles) {
    const perms = ROLES[role];
    if (perms) {
      perms.forEach((p) => permissions.add(p));
    }
  }
  return Array.from(permissions);
}

