function composeTRSInto(
  out: Float32Array,
  translation: number[] | undefined,
  rotation: number[] | undefined,
  scale: number[] | undefined,
): void {
  // Start with identity
  out[0] = 1; out[1] = 0; out[2] = 0; out[3] = 0;
  out[4] = 0; out[5] = 1; out[6] = 0; out[7] = 0;
  out[8] = 0; out[9] = 0; out[10] = 1; out[11] = 0;
  out[12] = 0; out[13] = 0; out[14] = 0; out[15] = 1;

  if (scale) {
    out[0]  *= scale[0];
    out[5]  *= scale[1];
    out[10] *= scale[2];
  }

  if (rotation && rotation.length >= 4) {
    // Convert quat to matrix and apply
    const qx = rotation[0], qy = rotation[1], qz = rotation[2], qw = rotation[3];
    const tx = scale?.[0] ?? 1, ty = scale?.[1] ?? 1, tz = scale?.[2] ?? 1;

    const x2 = qx + qx, y2 = qy + qy, z2 = qz + qz;
    const xx = qx * x2, xy = qx * y2, xz = qx * z2;
    const yy = qy * y2, yz = qy * z2, zz = qz * z2;
    const wx = qw * x2, wy = qw * y2, wz = qw * z2;

    out[0] = (1 - (yy + zz)) * (tx);
    out[1] = (xy + wz) * (tx);
    out[2] = (xz - wy) * (tx);
    out[4] = (xy - wz) * (ty);
    out[5] = (1 - (xx + zz)) * (ty);
    out[6] = (yz + wx) * (ty);
    out[8] = (xz + wy) * (tz);
    out[9] = (yz - wx) * (tz);
    out[10] = (1 - (xx + yy)) * (tz);
  }

  if (translation) {
    out[12] = translation[0];
    out[13] = translation[1];
    out[14] = translation[2];
  }
}

