  private static getComponentCount(type: string): number {
    switch (type) {
      case "SCALAR": return 1;
      case "VEC2":   return 2;
      case "VEC3":   return 3;
      case "VEC4":   return 4;
      case "MAT2":   return 4;
      case "MAT3":   return 9;
      case "MAT4":   return 16;
      default:       return 3;
    }
  }

