function extractFrustumPlanes(vp: Float64Array): Float64Array[] {
  // vp = projection * view (column-major)
  const planes: Float64Array[] = [];

  // Left   : row 3 + row 0
  // Right  : row 3 - row 0
  // Bottom : row 3 + row 1
  // Top    : row 3 - row 1
  // Near   : row 3 + row 2
  // Far    : row 3 - row 2

  const m = vp;
  const signs = [
    [ 1,  1,  1,  1], // left
    [-1, -1, -1, -1], // right
    [ 1,  1,  1,  1], // bottom
    [-1, -1, -1, -1], // top
    [ 1,  1,  1,  1], // near
    [-1, -1, -1, -1], // far
  ];

  const rowIndices = [
    [3, 0],  // left:   row3 + row0
    [3, 0],  // right:  row3 - row0
    [3, 1],  // bottom: row3 + row1
    [3, 1],  // top:    row3 - row1
    [3, 2],  // near:   row3 + row2
    [3, 2],  // far:    row3 - row2
  ];

  for (let p = 0; p < 6; p++) {
    const [r3, ri] = rowIndices[p];
    const sign = signs[p];
    const plane = new Float64Array(4);
    for (let i = 0; i < 4; i++) {
      plane[i] = m[r3 * 4 + i] + sign[i] * m[ri * 4 + i];
    }
    // Normalise
    const len = Math.sqrt(plane[0] * plane[0] + plane[1] * plane[1] + plane[2] * plane[2]);
    if (len > 0) {
      plane[0] /= len;
      plane[1] /= len;
      plane[2] /= len;
      plane[3] /= len;
    }
    planes.push(plane);
  }
  return planes;
}

