function sphereInFrustum(planes: Float64Array[], cx: number, cy: number, cz: number, r: number): boolean {
  for (let i = 0; i < 6; i++) {
    const p = planes[i];
    const d = p[0] * cx + p[1] * cy + p[2] * cz + p[3];
    if (d < -r) return false;
  }
  return true;
}

