export function sanitizeUrl(url: string): string {
  // Only allow http, https, mailto, and relative URLs
  if (/^(https?:\/\/|mailto:|\/)/.test(url)) {
    return url;
  }
  // Remove dangerous protocols
  return url.replace(/^(javascript|data|vbscript|file):/gi, '');
}

