  public processEvents(): void {
    while (this.eventQueue.length > 0) {
      const event = this.eventQueue.shift();
      if (event) {
        const handlers = this.state.events.get(event.eventId) || [];
        for (const handler of handlers) {
          handler(event.data);
        }
      }
    }
  }

