  private generateServiceWorker(): string {
    return `const CACHE_NAME = 'web-engine-v1';
const ASSETS = [
  './',
  './index.html',
  './main.js',
  './style.css',
  './manifest.json',
  './scene.json',
];

self.addEventListener('install', (event) => {
