  private lerpValues(a: number[], b: number[], t: number): number[] {
    const len = Math.min(a.length, b.length);
    const out = new Array<number>(len);
    for (let i = 0; i < len; i++) {
      out[i] = a[i] + (b[i] - a[i]) * t;
    }
    return out;
  }

