export function hashPassword(password: string): string {
  const salt = crypto.randomBytes(SALT_LENGTH).toString('hex');
  const hash = crypto.pbkdf2Sync(
    password,
    salt,
    PBKDF2_ITERATIONS,
    KEY_LENGTH,
    PBKDF2_DIGEST
  ).toString('hex');

  // Format: iterations:salt:hash
  return `${PBKDF2_ITERATIONS}:${salt}:${hash}`;
}

