        if (state === PluginLifecycleState.CREATED) {
          await plugin.init();
          this.states.set(plugin, PluginLifecycleState.INITIALIZED);
        } else {
          continue;
        }
      }
      try {
        await plugin.start();
        this.states.set(plugin, PluginLifecycleState.STARTED);
